// Some portions generated by Co-Pilot
import React from "react";
import { render, screen } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import { axe } from "vitest-axe";
import WhatWeDo from "../page";

describe("WhatWeDo page", () => {
  it("renders correctly", () => {
    const { container } = render(<WhatWeDo />);
    expect(container.firstChild).toMatchSnapshot();
  });

  it("has no accessibility violations", async () => {
    const { container } = render(<WhatWeDo />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("uses one primary heading and preserves the existing history and governance content", () => {
    const { container } = render(<WhatWeDo />);
    expect(screen.getAllByRole("heading", { level: 1 })).toHaveLength(1);
    expect(
      screen.getByRole("heading", {
        level: 1,
        name: "About Eclipse Adoptium®",
      }),
    ).toBeVisible();
    expect(
      screen.getByText(/AdoptOpenJDK project was established in 2017/),
    ).toBeVisible();
    expect(screen.getByText(/Projects under the Adoptium PMC/)).toBeVisible();
    expect(
      screen.getByText(/continuation of the original AdoptOpenJDK mission/),
    ).toBeVisible();
    expect(container.querySelector("a button")).not.toBeInTheDocument();
  });

  it("keeps all project links and uses an absolute locale-aware releases destination", () => {
    render(<WhatWeDo />);
    const destinations = [
      { name: "Eclipse Temurin®", href: "/temurin" },
      { name: "Eclipse AQAvit", href: "/aqavit" },
      { name: "Eclipse Mission Control", href: "/jmc" },
    ];
    for (const destination of destinations)
      expect(
        screen.getByRole("link", { name: destination.name }),
      ).toHaveAttribute("href", destination.href);
    expect(
      screen.getByRole("link", { name: "See all Releases" }),
    ).toHaveAttribute("href", "/temurin/releases");
  });

  it("retains all three license destinations and their attribution context", () => {
    render(<WhatWeDo />);
    const licenses = [
      {
        name: "Apache License, Version 2.0",
        href: "https://www.apache.org/licenses/LICENSE-2.0",
      },
      {
        name: "GPL v2 with Classpath Exception",
        href: "https://openjdk.java.net/legal/gplv2+ce.html",
      },
      {
        name: "GPL v2 with Assembly Exception",
        href: "https://openjdk.java.net/legal/assembly-exception.html",
      },
    ];
    for (const license of licenses) {
      const link = screen.getByRole("link", { name: license.name });
      expect(link).toHaveAttribute("href", license.href);
      expect(link).toHaveAttribute("rel", "noopener noreferrer");
    }
    expect(
      screen.getByText(/Build scripts and other code to produce the binaries/),
    ).toBeInTheDocument();
    expect(
      screen.getByText(/OpenJDK code itself is licensed under/),
    ).toBeInTheDocument();
  });
});
